// TH14 synthetic training aliases (transcribe/th14/touhou-bullets.ecl).
// Native type 0..23 -> catalog 0..23; native 24..42 -> catalog 25..43.
// Only the types this card spawns are copied here.
const TH14_NOTE_RED: int = 976;   // native etSprite type 38, color slot 0

// th14_s4_b7 — TH14 v1.00b stage 4 boss (route B), nonspell BossB1.
// Entry: st04bs2.ecl.txt BossB preamble 10-39 + BossB1 60-90.
// Dependencies transcribed inline: BossB1_at 92-136, EffChargePoint3 188-200 (pure ANM/sound, dropped).
// Target shell: independent invincible enemy + control enemy carrying the segment (validation.md).

const TIME_LIMIT: int = 3128;      // 120 opening + 3004 window + 4 start margin
const OPENING_BUFFER: int = 120;
const SEGMENT_FRAMES: int = 2400;  // native slot-0 interrupt time (source line 63)

// Source BossB1_at EX chain (lines 116-121), appended in this order:
//   ANIM a=1                  -> birth ANIM omitted (approved), retreat kept via sh_dist below
//   ANGLE_ACCEL a=40 r=+0.016 s=+0.008*RANDF2
//   ANGLE_ACCEL a=40 r=+0.015 s=+0.008*RANDF2
//   ANGLE_ACCEL a=40 r=-0.015 s=+0.008*RANDF2
//   ANGLE_ACCEL a=40 r= 0     s=+0.008*RANDF2
//   GOTO 4                    -> the last record repeats forever: accel 0, spin s4 stays
xformdef S4_ANGLE_ACCEL(s1: angle, s2: angle, s3: angle, s4: angle) {
    set_accel(0.016fx);
    set_ang_vel(s1);
    wait(40);
    set_accel(0.015fx);
    set_ang_vel(s2);
    wait(40);
    set_accel(-0.015fx);
    set_ang_vel(s3);
    wait(40);
    set_accel(0fx);
    set_ang_vel(s4);
}

// One etOn(0) wave of BossB1_at_100..etOn (source lines 98-122).
// Random read order matches the source: RANDRAD, RANDF2 x2 (etOffset), RANDF2 x4 (EX s).
sub wave(speed: fx, dist: fx) {
    var base: int = rand(65536) - 32768;                        // %RANDRAD: -pi..pi in BAM
    var ux: fx = (rand(65536) - 32768) as fx / 32768;           // %RANDF2 for etOffset x
    var uy: fx = (rand(65536) - 32768) as fx / 32768;           // %RANDF2 for etOffset y
    var s1: angle = ((rand(65536) - 32768) / 393) as angle;     // 0.008 rad/frame ~ 83.4 BAM
    var s2: angle = ((rand(65536) - 32768) / 393) as angle;
    var s3: angle = ((rand(65536) - 32768) / 393) as angle;
    var s4: angle = ((rand(65536) - 32768) / 393) as angle;

    sh_reset(0);
    sh_sprite(0, TH14_NOTE_RED, 0);              // etSprite(0, 38, 0)
    sh_ring(0, 1);                               // etAim(0, 3): fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, 24, 1);                          // etCount(0, 24, 1)
    sh_angle(0, base as angle, 341bam);          // etAngle(0, RANDRAD, 0.0327) delta unused at 1 layer
    sh_speed(0, speed, 0fx);                     // etSpeed(0, rank speed, 1.0) with M=1 -> s0 only
    sh_dist(0, dist);                            // etDist 32 with ANIM birth retreat -4*speed
    sh_offset(0, 12fx + 32fx * ux, -12fx + 32fx * uy);   // etOffset(0, 12+RANDF2*32, -12+RANDF2*32)
    sh_xform(0, S4_ANGLE_ACCEL(s1, s2, s3, s4));
    sh_fire(0);                                  // etOn(0)
}

// One async call of BossB1_at: 1200 iterations bounded by the 2400-frame segment timeout.
async sub shots(interval: int, speed: fx, dist: fx, bursts: int) {
    for k in 0..bursts {
        wave(speed, dist);
        wait(interval);                          // rank wait([-1]): 48 / 20 / 12 / 8
    }
}

// moveRand(60, 4, speed) recipe from transcribe/th16/movement.md, limits retuned to
// moveLimit(0, 128, 280, 64): x in [-140,140], y in [64,192]; inner region x +-70, y 112..144.
// int slot 1 = next step index, fx slots 1/2 = logical unit direction.
// (Source F0=0.017453 / I0=2 live in fx0 / int0; nothing in this closure reads them.)
sub move_arm(speed: fx) {
    var k: int = self_int(1) + 1;
    set_self_int(1, k);
    var sp: fx = 0fx;
    if k < 60 { sp = ((60 - k) as fx / 60fx) * speed; }   // speed(k) = speed * (1 - k/60)
    var nx: fx = $self_x + self_fx(1) * sp;
    var ny: fx = $self_y + self_fx(2) * sp;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 64fx { ny = 64fx; }
    if ny > 192fx { ny = 192fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_wait(frames: int, speed: fx) {
    for i in 0..frames {
        wait(1);
        move_arm(speed);
    }
}

sub move_rand(speed: fx) {
    var r: int = rand(65536) - 32768;                 // signed unit random * pi
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(1, cos(a as angle));
    set_self_fx(2, sin(a as angle));
    set_self_int(1, 0);
    move_arm(speed);
}

async sub boss() {
    var rank: int = global(GVAR_RANK);
    var gap: int = 80;            // !E/!N/!H wait 80 before moveRand
    var interval: int = 48;       // !E
    var speed: fx = 0.4fx;        // !E/!N
    var cycles: int = 11;         // floor(2400 / 210)
    if rank == RANK_NORMAL {
        interval = 20;            // !N
    }
    if rank == RANK_HARD {
        interval = 12;            // !H
        speed = 0.9fx;            // !H
    }
    if rank == RANK_LUNATIC {
        interval = 8;             // !LO takes the L value
        speed = 1fx;              // !LO takes the L value
        gap = 20;
        cycles = 16;              // 2400 / 150
    }

    // BossB preamble 10-39 (dialogWait and pure ANM/sound omitted, explicit waits kept).
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);   // flagSet(3) body-off part; unconfirmed 0x1 bit not mapped
    set_hitbox(12fx);                   // default 24x24 -> radius 12
    set_hurtbox(12fx);
    move_to(0, 0fx, 128fx, EASE_LINEAR); // movePos(0, 128)
    wait(102);
    set_enemy_flag(ENEMY_NO_BODY, 0);   // flagClear(3)
    set_hitbox(24fx);                   // setHitbox(48, 48)
    set_hurtbox(24fx);                  // setHurtbox(48, 48)
    wait(1);                            // explicit waits between the omitted dialogWait calls
    wait(1);

    // BossB1 62-71: timerReset/star/anm are presentation; async helper then F0/I0 in source order.
    spawn shots(interval, speed, 32fx - 4fx * speed, SEGMENT_FRAMES / interval);
    set_self_fx(0, 0.017453fx);
    set_self_int(0, 2);

    // BossB1_344..512: wait 60, wait 80 (20 on L), moveRand(60,4,0.4), wait 70.
    // moveRand's speed is the literal 0.4 of source line 85, independent of the rank bullet speed.
    for c in 0..cycles {
        wait(60);
        wait(gap);
        move_rand(0.4fx);
        move_wait(70, 0.4fx);
    }
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13300, 0, 0, 0, boss);   // lifeSet(13300), moveLimit start point
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
